package com.campusnova.model;
import javax.persistence.*; import java.time.LocalDateTime;
@Entity public class ChatHistory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String sessionId; @Column(length=1000) private String question; @Column(length=5000) private String response; private String category; private boolean answered; private String responseType="FALLBACK"; private boolean outOfDomain=false; private long responseTimeMs; private LocalDateTime createdAt=LocalDateTime.now();
 public ChatHistory(){} public ChatHistory(String s,String q,String r,String c,boolean a){this(s,q,r,c,a,"FALLBACK",false,0);} public ChatHistory(String s,String q,String r,String c,boolean a,String type,boolean outside,long time){sessionId=s;question=q;response=r;category=c;answered=a;responseType=type;outOfDomain=outside;responseTimeMs=time;} public Long getId(){return id;} public String getSessionId(){return sessionId;} public String getQuestion(){return question;} public String getResponse(){return response;} public String getCategory(){return category;} public boolean isAnswered(){return answered;} public String getResponseType(){return responseType;} public boolean isOutOfDomain(){return outOfDomain;} public long getResponseTimeMs(){return responseTimeMs;} public LocalDateTime getCreatedAt(){return createdAt;} }
